async function openAccount(){if(authClient){const{data}=await authClient.auth.getSession();renderAccount(data?.session?.user||null,'signin')}else renderAccount(null,'signin');openPanel('#accountModal')}async function requireSignIn(action,message){if(!authClient){await openAccount();const status=$('#authMessage');if(status)status.textContent='Sign-in is unavailable until the account service is connected.';return false}try{const{data,error}=await authClient.auth.getSession();if(!error&&data?.session?.user)return true}catch{}pendingAccountAction=action;await openAccount();const status=$('#authMessage');if(status)status.textContent=message;return false}function completeSignIn(user){renderAccount(user);const action=pendingAccountAction;pendingAccountAction=null;if(action){closePanels();setTimeout(action,0)}}
function openLinkedProduct(){if(!location.hash.startsWith('#product-'))return;const id=decodeURIComponent(location.hash.slice(9));if(products.some(product=>product.id===id))productModal(id)}
function updateProductAvailability(productId){if(!$('#productModal')||$('#productModal').classList.contains('hidden')||decodeURIComponent(location.hash.slice(9))!==String(productId))return;const product=products.find(item=>String(item.id)===String(productId));if(!product)return;const size=$('#productModalContent [data-size].active')?.dataset.size||product.sizes?.[0]||'One size',color=$('#productModalContent [data-color].active')?.dataset.color||product.colors?.[0]||'',stock=variantStockFor(product,size,color),managed=Object.keys(product.variant_stock||{}).length>0,inBag=cart.filter(item=>String(item.id)===String(productId)&&(!managed||(item.size===size&&item.color===color))).reduce((sum,item)=>sum+Number(item.qty||0),0),status=$('#productModalContent .stock'),addButton=$('#addToBag'),buyButton=$('#buyNow');if(status){status.classList.toggle('low-stock',stock>0&&stock<6);status.innerHTML=`<span class="stock-dot"></span>${stock<=0?'Currently sold out in this selection':inBag>=stock?`All ${stock} available ${stock===1?'piece is':'pieces are'} in your bag`:stock<6?`Only ${stock} left · Ready to ship`:`${stock} in stock · Ready to ship`}`}if(addButton)addButton.disabled=stock<=0||inBag>=Math.min(10,stock);if(buyButton)buyButton.disabled=stock<=0}
async function refreshProductStock(productId){if(!authClient)return;try{const[{data,error},{data:variants,error:variantError}]=await Promise.all([authClient.from('store_products').select('id,stock,active').eq('id',String(productId)).maybeSingle(),authClient.from('store_product_variants').select('product_id,size,color,stock').eq('product_id',String(productId))]);if(error||!data||data.active===false)return;const product=products.find(item=>String(item.id)===String(productId));if(!product)return;product.stock=Math.max(0,Math.floor(Number(data.stock)||0));if(!variantError&&Array.isArray(variants)){product.variant_stock={};for(const row of variants)product.variant_stock[JSON.stringify([normalizedVariantSize(row.size),String(row.color||'').trim()])]=Number(row.stock)||0}render();updateProductAvailability(productId)}catch{}}
