if(authClient)authClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){renderPasswordRecovery(session?.user||null);openPanel('#accountModal');return}if(event==='SIGNED_IN'&&session?.user){completeSignIn(session.user);void resumePaymentReturn();}else if(event==='INITIAL_SESSION'||event==='SIGNED_OUT')renderAccount(session?.user||null)});
function renderSearchResults(query){
 const root=$('#searchResults'),term=String(query||'').trim().toLowerCase();
 if(!root)return;
 const matches=term?products.filter(product=>`${product.name} ${product.category} ${product.desc}`.toLowerCase().includes(term)).slice(0,5):products.slice(0,3);
 root.innerHTML=matches.length?matches.map(product=>`<button class="search-result" type="button" data-product="${escapeHtml(product.id)}"><img src="${escapeHtml(product.image)}" alt=""><span><b>${escapeHtml(product.name)}</b><small>${escapeHtml(product.category)} · ${money(product.price)}</small></span><span aria-hidden="true">↗</span></button>`).join(''):`<p class="search-empty">No pieces found. Try “churidar”, “kurta” or “cotton”.</p>`;
 root.querySelectorAll('img').forEach(image=>image.addEventListener('error',()=>image.classList.add('broken'),{once:true}));
}
